import { join } from 'node:path';
import { createAutomationAction, createAutomationSession, createChatThread, createMemoryNode, createStoredChatMessage } from '@ultron/core';
import { SqliteMemoryRepository } from './packages/storage/src/index.ts';

const dir = mkdtempSync(join(tmpdir(), 'ultron-storage-hidden-'));
const repo = new SqliteMemoryRepository(join(dir, 'test.sqlite'));
await repo.migrate();
try {
  for (let index = 0; index < 1002; index += 1) {
    await repo.upsertNode(createMemoryNode({
      type: 'semantic',
      title: `Node ${index}`,
      summary: `Broad limit node ${index}`,
      body: `Searchable body ${index}`,
      tags: ['limit'],
      confidence: 0.8,
      importance: 0.5,
      source: 'hidden-test',
      sourceConversationId: null,
      ownerUserId: 'local-user',
      projectId: 'ultron',
      parentNodeId: null,
      linkedNodeIds: [],
      visibility: 'project',
      sensitivity: 'low',
      status: 'active',
      metadata: {},
      markdownPath: null
    }));
  }
  assert.equal((await repo.listNodes({ ownerUserId: 'local-user', limit: 10_000 })).length, 1000);
  assert.equal((await repo.listNodes({ ownerUserId: 'local-user', limit: 0 })).length, 250);
  assert.equal((await repo.searchNodes({ ownerUserId: 'local-user', text: 'broad', limit: 10_000 })).length, 1000);
  assert.equal((await repo.searchNodes({ ownerUserId: 'local-user', text: 'broad', limit: 0 })).length, 25);

  for (let index = 0; index < 1002; index += 1) {
