  }
  assert.equal((await repo.listChatThreads({ ownerUserId: 'local-user', limit: 10_000 })).length, 1000);
  assert.equal((await repo.listChatThreads({ ownerUserId: 'local-user', limit: 0 })).length, 100);

  const thread = await repo.createChatThread(createChatThread({ title: 'Hidden chat', ownerUserId: 'local-user', projectId: 'ultron' }));
  for (let index = 0; index < 1002; index += 1) {
    await repo.appendChatMessage(createStoredChatMessage({ chatId: thread.id, role: index % 2 === 0 ? 'user' : 'assistant', content: `Message ${index}`, contextPacket: null }));
  }
  assert.equal((await repo.listChatMessages(thread.id, 10_000)).length, 1000);
  assert.equal((await repo.listChatMessages(thread.id, 0)).length, 200);

  for (let index = 0; index < 1002; index += 1) {
    await repo.createAutomationSession(createAutomationSession({ ownerUserId: 'local-user', projectId: 'ultron', conversationId: null, kind: 'browser', goal: `Goal ${index}` }));
  }
