  assert.equal((await repo.listAutomationSessions({ ownerUserId: 'local-user', limit: 0 })).length, 100);

  const session = await repo.createAutomationSession(createAutomationSession({ ownerUserId: 'local-user', projectId: 'ultron', conversationId: null, kind: 'browser', goal: 'Hidden session' }));
  for (let index = 0; index < 1002; index += 1) {
    await repo.appendAutomationAction(createAutomationAction({ sessionId: session.id, parentActionId: null, sequence: index, actor: 'browser', targetKind: 'browser', targetRef: null, actionType: 'observe', input: {}, status: 'completed' }));
  }
  assert.equal((await repo.listAutomationActions(session.id, 10_000)).length, 1000);
  assert.equal((await repo.listAutomationActions(session.id, 0)).length, 500);

  assert.equal((await repo.listEvents({ limit: 10_000 })).length, 1000);
  assert.equal((await repo.listEvents({ limit: 0 })).length, 100);
} finally {
  await repo.close();
  rmSync(dir, { recursive: true, force: true });
}
