const { readFileSync } = require('node:fs');
const source = readFileSync('packages/storage/src/index.ts', 'utf8');
const count = (needle) => source.split(needle).length - 1;
const expected = new Map([
  ['normalizeLimit(filter.limit, 250)', 2],
  ['normalizeLimit(query.limit, 25)', 2],
  ['normalizeLimit(filter.limit, 100)', 6],
  ['normalizeLimit(limit, 200)', 4],
  ['normalizeLimit(limit, 500)', 2]
]);
for (const [needle, expectedCount] of expected) {
  const actual = count(needle);
  if (actual !== expectedCount) {
    throw new Error(`${needle} expected ${expectedCount} occurrence(s), got ${actual}`);
  }
}
for (const forbidden of ['filter.limit ?? 250', 'query.limit ?? 25', 'filter.limit ?? 100']) {
  if (source.includes(forbidden)) {
    throw new Error(`raw fallback remained: ${forbidden}`);
  }
}
